                "вопроса. Вместо «сколько документов?» спросите «сколько событий произошло?»",
                "Здесь два разных события: компания перечислила деньги и получила кресла. Каждое событие",
                "может иметь несколько подтверждений. Именно связь между событием и документом, а не",
                "количество файлов, должна управлять вашей проверкой.",
                "Разбираем движение по этапам",
