                "2. Что такое первичный документ — на языке работы",
                "Первичный учётный документ оформляет факт хозяйственной жизни. Это не просто «бумага с",
                "печатью». Он позволяет понять, что произошло, когда, между кем, в каком объёме и кто отвечает",
                "за оформление. С 2013 года для большинства организаций не действует общий принцип",
                "«использовать только унифицированный бланк»: формы утверждаются экономическим",
                "субъектом с учётом требований закона. Однако для отдельных операций существуют",
                "специальные правила и формы. Поэтому не стоит считать документ неправильным лишь потому,",
                "что он выглядит не так, как образец из интернета.",
                "Статья 9 Федерального закона № 402-ФЗ «О бухгалтерском учёте» устанавливает обязательные",
                "реквизиты первичного документа. Наличие всех полей не гарантирует, что сделка реальна, но",
                "отсутствие обязательного реквизита требует разбирательства. Договор и переписка помогают",
                "проверить содержание операции, хотя не всегда заменяют первичный документ.",
                "Семь обязательных групп реквизитов",
                "Реквизит                       На что смотрим                  Типичный риск",
                "Наименование                   Что это за документ             Неясно, какой факт оформлен",
                "Дата составления               Когда документ оформлен         Период учёта определён",
                "неверно",
                "Наименование составителя       Кто составил документ           Нельзя идентифицировать",
                "сторону",
                "Содержание факта               Какие товары, услуги, работы    «Услуги» без конкретики не",
