                "Профессиональная привычка: проверяйте не только наличие поля, но и его смысл. В строке",
                "«оказаны услуги» можно формально увидеть описание, но для реальной сверки часто",
                "понадобится детализация по договору, приложению или отчёту исполнителя.",
                "3. Счёт на оплату: почему его нельзя путать с актом",
                "Счёт сообщает, кому, сколько и за что предлагается заплатить. Он помогает организовать",
                "оплату, но обычно не доказывает, что товар передан или услуга оказана. Счёт может быть",
                "выставлен до выполнения обязательств. В некоторых сделках он участвует в согласовании",
                "условий, однако бухгалтерская роль документа определяется реальной ситуацией и договором.",
                "Пример. Студия заказала дизайн упаковки за 45 000 ₽. Исполнитель выставил счёт 1 октября.",
                "Оплата прошла 2 октября, а макеты приняты 18 октября по акту. Если помощник запишет «услуга",
                "оказана 2 октября», он перепутает оплату с выполнением работ. Правильная связка: счёт →",
                "оплата → выполнение → документ приёмки.",
                "Мини-тренажёр",
                "Счёт выставлен 4 ноября на 15 900 ₽, оплата прошла 5 ноября, акт подписан 19 ноября. Что",
                "можно уверенно сказать на 5 ноября? Деньги перечислены. А вот утверждать, что услуга уже",
                "оказана, без иных подтверждений нельзя.",
                "4. Акт: что он доказывает и что в нём проверять",
                "Акт обычно оформляет оказание услуг, выполнение работ, приёмку этапа. Его содержание",
                "должно быть соотносимо с договором: «консультационные услуги» может оказаться",
                "недостаточно конкретным для внутренней проверки, если договор предусматривает пять",
                "отдельных консультаций и отчёт. Внимание к периоду особенно важно для ежемесячных услуг:",
                "октябрьский акт не должен незаметно заменить сентябрьский.",
                "Пример. Договор предусматривает поддержку сайта за 12 000 ₽ в месяц. Пришёл акт на 24 000 ₽",
                "за октябрь. Это не обязательно мошенничество: могли включить дополнительную работу. Но",
                "помощник не должен решать это догадкой. Он сверяет приложение к договору, заказ",
                "дополнительных работ и переписку, затем фиксирует вопрос бухгалтеру.",
                "Что записать в запросе",
                "«Акт № 48 от 31.10 на 24 000 ₽. По договору ежемесячная поддержка — 12 000 ₽. Прошу",
                "подтвердить дополнительные услуги на 12 000 ₽ либо запросить исправленный акт. До уточнения",
                "статус: “расхождение суммы”». Это рабочая формулировка: она содержит документ, сумму,",
                "источник сравнения и конкретное действие.",
                "5. Накладная: количество важнее красивой итоговой суммы",
                "Для товаров критично сверить количество, ассортимент и факт передачи. Представьте, что по",
                "заказу нужно 20 коробок бумаги по 500 ₽, всего 10 000 ₽. В накладной 20 коробок по 500 ₽, но",
                "склад принял 18. На бумаге сумма совпадает с заказом, однако фактическая приёмка отличается",
                "на две коробки, то есть на 1 000 ₽. Нельзя механически подтвердить 20 коробок только потому,",
                "что поставщик так написал.",
                "Помощник выясняет, есть ли отметка о расхождении, акт о недостаче, переписка с поставщиком,",
                "исправленный документ или согласованный порядок допоставки. Окончательное оформление",
                "зависит от условий договора и принятой процедуры приёмки.",
                "6. УПД: один файл, несколько функций",
                "Универсальный передаточный документ может использоваться для оформления передачи",
                "товаров, работ или услуг и, при соблюдении требований, совмещать сведения передаточного",
                "документа и счёта-фактуры. Важно различать назначение конкретного УПД и его заполнение:",
                "нельзя по одному заголовку заключить, что все налоговые требования выполнены. Для работы с",
                "НДС нужно учитывать действующие правила и электронные форматы.",
                "УПД не отменяет проверку фактической поставки. Если в нём указаны 8 ноутбуков, а организация",
                "получила 7, расхождение остаётся независимо от того, бумажный документ или электронный.",
                "Электронная подпись подтверждает определённые юридически значимые действия, но не делает",
                "ошибочную цифру автоматически правильной.",
                "7. Одна операция — несколько документов: учимся связывать",
                "У начинающего помощника самая дорогая ошибка — двойное отражение. Поставщик прислал",
                "счёт на 30 000 ₽, затем УПД на 30 000 ₽, а менеджер переслал ещё и скан того же УПД. В папке",
                "три файла, но поставка одна. Проверка дубля начинается с идентификаторов: контрагент, номер,",
                "дата, сумма, предмет, период. Совпадение суммы недостаточно: у компании могут быть две",
                "реальные поставки по 30 000 ₽.",
