                "20. Критерии оценки практики",
                "Пять баллов — правильно определены группы документов; пять — найдены и объяснены",
                "расхождения; пять — корректно разделены движения денег и экономические события; пять —",
                "сформулированы точные вопросы бухгалтеру. Максимум 20 баллов. Результат 17–20: готовность",
                "переходить к уроку 2. Результат 13–16: повторите документы и авансы. До 13: вернитесь к",
                "разделам 1, 4 и 8, затем решите задачу ещё раз.",
                "Не стремитесь угадывать то, чего нет в документах. В бухгалтерской работе фраза «нужна",
                "дополнительная информация» при правильно названной причине — признак профессионального",
                "мышления, а не слабости.",
