                "денег.",
                "Прибыль — Финансовый результат после сопоставления доходов и расходов по применимым",
                "правилам.",
                "Актив — Экономический ресурс, контролируемый организацией.",
                "Обязательство — Существующая обязанность перед другой стороной.",
                "Первичный документ — Документ, оформляющий факт хозяйственной жизни.",
                "Проводка — Запись операции по дебету и кредиту счетов.",
                "Реестр — Структурированный список операций или документов со статусами.",
                "Методическое примечание: примеры носят учебный характер. Перед коммерческой публикацией",
