                "22. Читаем банковскую выписку как расследование, а не как список",
                "сумм",
                "Бухгалтерская выписка полезна только тогда, когда каждая строка связана с конкретным",
                "основанием. Давайте потренируемся на данных малого бизнеса — студии печати «Линия».",
